outputFormat.schema:
{
  "type": "object",
  "properties": {
    "lead_score": { "type": "integer" },
    "routing_action": {
      "type": "string",
      "enum": ["Route to AE", "Route to SDR", "Nurture", "Disqualify", "Insufficient information"]
    },
    "decision_maker": { "type": "boolean" },
    "budget_mentioned": { "type": "boolean" },
    "primary_pain": { "type": "string" },
    "timeline_signal": { "type": "string" },
    "data_gaps": { "type": "string" }
  },
  "required": ["lead_score", "routing_action", "decision_maker", "budget_mentioned", "primary_pain", "timeline_signal", "data_gaps"],
  "additionalProperties": false
}
